const TIMEOUT = 4000;
/** install: wait (ms) before each round of attempts at a file; each round tries a revalidating fetch, then ?v=<sha> */
const ROUNDS = [0, 1000, 3000];
/** install: give up on an attempt once no bytes have arrived for this long (a dead socket is retried
 *  quickly, while a slow but live download of the ~900 KB shell still finishes), or after ATTEMPT_MS */
const STALL_MS = 10000;
const ATTEMPT_MS = 120000;
/** install: files fetched at once */
const PARALLEL = 4;
const RUNTIME_MAX = 64;

const scope = self.registration.scope;
const SHELL = scope; // './' is index.html
const abs = (p) => new URL(p, scope).href;
/** absolute URL -> sha256 */
const SHA = new Map(PRECACHE.map(([p, sha]) => [abs(p), sha]));
const SW = abs('sw.js');
/** a cache lookup that never creates the cache it names (caches.open would) */
const find = (key, cacheName) => caches.match(key, { cacheName, ignoreVary: true });

async function sha256(buf) {
  const d = new Uint8Array(await crypto.subtle.digest('SHA-256', buf));
  return Array.from(d, (b) => b.toString(16).padStart(2, '0')).join('');
}

/** A plain 200 response with these bytes (no redirect flag, no Vary): safe to answer a navigation with. */
function stored(res, body) {
  const headers = new Headers();
  for (const h of ['content-type', 'last-modified', 'etag']) if (res.headers.has(h)) headers.set(h, res.headers.get(h));
  return new Response(body, { status: 200, headers });
}

/** Our precache caches, this build's first. */
async function precaches() {
  const names = (await caches.keys()).filter((k) => k.startsWith(PREFIX) && k !== RUNTIME && k !== CACHE);
  return [CACHE, ...names];
}

/** The file's bytes from any littlewick cache, if they are exactly this build's. */
async function reuse(url, sha) {
  for (const name of await precaches()) {
    const res = await find(url, name);
    if (!res) continue;
    const body = await res.arrayBuffer();
    if ((await sha256(body)) === sha) return { res: stored(res, body), own: name === CACHE };
  }
  return null;
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/** The response body, calling alive() whenever bytes arrive. */
async function readAll(res, alive) {
  if (!res.body || !res.body.getReader) return res.arrayBuffer();
  const reader = res.body.getReader();
  const parts = [];
  let n = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    alive();
    parts.push(value);
    n += value.byteLength;
  }
  const out = new Uint8Array(n);
  let at = 0;
  for (const p of parts) { out.set(p, at); at += p.byteLength; }
  return out.buffer;
}

async function download(url, sha) {
  let why = 'not tried';
  for (let round = 0; round < ROUNDS.length; round++) {
    if (ROUNDS[round]) await sleep(ROUNDS[round]);
    // revalidate past the HTTP cache, then a URL no cache on the way has seen
    const bust = url + '?v=' + sha.slice(0, 16) + (round ? '.' + round : '');
    for (const [u, cache] of [[url, 'no-cache'], [bust, 'reload']]) {
      const ac = new AbortController();
      let stall = 0;
      const alive = () => { clearTimeout(stall); stall = setTimeout(() => ac.abort(), STALL_MS); };
      const cap = setTimeout(() => ac.abort(), ATTEMPT_MS);
      alive();
      try {
        const res = await fetch(u, { cache, credentials: 'same-origin', signal: ac.signal });
        alive();
        if (!res.ok) { why = 'HTTP ' + res.status; continue; }
        const body = await readAll(res, alive);
        if ((await sha256(body)) !== sha) { why = 'bytes differ from this build'; continue; }
        return stored(res, body);
      } catch (err) {
        why = ac.signal.aborted ? 'stalled' : String((err && err.message) || err);
      } finally {
        clearTimeout(stall);
        clearTimeout(cap);
      }
    }
  }
  throw new Error('precache ' + url + ': ' + why);
}

/** Put every listed file into this build's cache (copied or downloaded, always verified). */
async function fill(list) {
  const cache = await caches.open(CACHE);
  const queue = list.slice();
  const failed = [];
  const worker = async () => {
    // after a failure every lane stops, and all writes settle before the caller cleans up
    for (let e; !failed.length && (e = queue.shift());) {
      try {
        const url = abs(e[0]);
        const got = await reuse(url, e[1]);
        if (got && got.own) continue;
        await cache.put(url, got ? got.res : await download(url, e[1]));
      } catch (err) {
        failed.push(err);
      }
    }
  };
  await Promise.all(Array.from({ length: Math.min(PARALLEL, queue.length) }, worker));
  if (failed.length) throw failed[0];
}

/** PRECACHE entries this build's cache lacks. */
async function missing() {
  const have = new Set((await (await caches.open(CACHE)).keys()).map((r) => r.url));
  return PRECACHE.filter(([p]) => !have.has(abs(p)));
}

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    try {
      await fill(PRECACHE);
      const gap = await missing();
      if (gap.length) throw new Error('precache incomplete: ' + gap.map(([p]) => p).join(' '));
    } catch (err) {
      // never leave a half-filled cache that looks like a build: the worker in charge keeps serving
      await caches.delete(CACHE);
      throw err;
    }
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    // install only finishes with a complete cache; this covers storage cleared in between
    let gap = await missing();
    if (gap.length) { try { await fill(gap); } catch { /* keep the old caches */ } gap = await missing(); }
    if (!gap.length) {
      for (const k of await caches.keys()) if (k.startsWith(PREFIX) && k !== CACHE && k !== RUNTIME) await caches.delete(k);
    }
    await self.clients.claim();
  })());
});

/**
 * This build's cache has vanished (storage evicted, or another app on the shared github.io origin deleted
 * it) while this worker still serves: fill it again, as install would. Not when another build's cache is
 * there (a newer worker has taken over, or is about to). One at a time; a failed fill leaves no cache.
 */
let healing = null;
function heal() {
  if (healing) return healing;
  healing = (async () => {
    if (await caches.has(CACHE)) return;
    if ((await caches.keys()).some((k) => k.startsWith(PREFIX) && k !== RUNTIME && k !== CACHE)) return;
    try {
      await fill(PRECACHE);
      if ((await missing()).length) throw new Error('precache incomplete');
    } catch {
      await caches.delete(CACHE);
    }
  })().finally(() => { healing = null; });
  return healing;
}

/**
 * Put a precached file the network just served back into this build's cache, only if the cache lacks it
 * and its bytes are exactly this build's: the cache stays one verified build (an online launch while a
 * newer deploy is out, or half out, must not mix that deploy's shell into it).
 */
async function refresh(key, res) {
  // (a worker that a newer build just replaced must not recreate the cache it deleted)
  if (!(await caches.has(CACHE)) || (await find(key, CACHE))) return;
  const body = await res.arrayBuffer();
  if ((await sha256(body)) !== SHA.get(key)) return;
  if (await caches.has(CACHE)) await (await caches.open(CACHE)).put(key, stored(res, body));
}

/** A navigation must not be answered with a redirected response: copy it into a fresh one. */
function clean(res) {
  if (!res.redirected) return res;
  return new Response(res.body, { status: res.status, statusText: res.statusText, headers: res.headers });
}

async function lookup(names, key) {
  for (const name of names) {
    const res = await find(key, name);
    if (res) return res;
  }
  return undefined;
}

async function trim() {
  const c = await caches.open(RUNTIME);
  const keys = await c.keys();
  for (const k of keys.slice(0, Math.max(0, keys.length - RUNTIME_MAX))) await c.delete(k);
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET' || req.headers.has('range')) return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin || !url.href.startsWith(scope)) return;
  const bare = url.origin + url.pathname;
  if (bare === SW) return;
  const nav = req.mode === 'navigate';
  if (nav) event.waitUntil(heal());
  // where this request lives: the shell for the scope root / index.html whatever the query, a precached
  // file by its path, anything else (not a navigation) in the runtime cache under its full URL
  const shell = bare === SHELL || bare === SHELL + 'index.html';
  const key = shell ? SHELL : SHA.has(bare) ? bare : null;
  const runtime = !key && !nav;

  let put = Promise.resolve();
  const net = fetch(nav ? url.href : req, nav ? { cache: 'no-cache', credentials: 'same-origin' } : { cache: 'no-cache' })
    .then((res) => {
      // a precached file (at its bare URL, so a query can never store a different resource under it; the
      // shell at any query) refills a missing entry of this build's cache, if its bytes are this build's;
      // anything else is cached on first use
      const keep = runtime || shell || (key && !url.search);
      if (keep && res.ok && res.status === 200 && res.type === 'basic' && !res.redirected) {
        const copy = res.clone();
        put = (key ? refresh(key, copy) : caches.open(RUNTIME).then((c) => c.put(req, copy)).then(trim)).catch(() => {});
      }
      return res;
    });
  event.waitUntil(net.then(() => put, () => {}));

  event.respondWith((async () => {
    // offline answer: a precached file its own entry (any query), any other navigation the shell
    const cached = async () => (nav || key)
      ? lookup(await precaches(), key || SHELL)
      : lookup([RUNTIME], req);
    let timer;
    const late = new Promise((resolve) => { timer = setTimeout(resolve, TIMEOUT, 'timeout'); });
    try {
      const res = await Promise.race([net, late]);
      if (res !== 'timeout') {
        // a server error on launch, or a missing file mid-deploy: the cached copy beats an error page
        if ((nav && res.status >= 500) || (key && !res.ok)) { const c = await cached(); if (c) return c; }
        return clean(res);
      }
      const c = await cached();
      if (c) return c;
      return clean(await net);
    } catch (err) {
      const c = await cached();
      if (c) return c;
      throw err;
    } finally {
      clearTimeout(timer);
    }
  })());
});
